#include "ksMidiFileTransportTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::MidiFileTransportTask;using S=T::Stage;using C=T::Child;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;auto verify=[&](unsigned key,unsigned control,bool available,unsigned mode,bool firstDue){T t;std::array<uint8_t,18>state{},saved{},old{};for(unsigned i=0;i<18;++i)state[i]=uint8_t(i*17+key+control);state[16]=uint8_t(mode);old=state;unsigned dueCalls=0,events=0,polls=0,controls=0,releases=0,delays=0,tempo=0,stopped=0,timeReset=0,division=0;bool playing=true;std::vector<C>children;unsigned guard=0;while(!t.complete()){check(++guard<1000,"Transport pure stalled");if(t.awaitingChild()){auto c=t.child();children.push_back(c);if(c==C::Due){++dueCalls;check(t.resumeDue(dueCalls>1||firstDue),"Transport duereply");}else if(c==C::Event){++events;playing=false;check(t.resumeSource(t.stream()+3),"Transport eventreply");}else if(c==C::Delay){++delays;check(t.resumeSource(t.stream()+1),"Transport delayreply");}else if(c==C::PollKey){++polls;check(t.resumeKey(uint8_t(key)),"Transport keyreply");}else if(c==C::PollControl){++controls;check(t.resumeControl(available,uint8_t(control)),"Transport controlreply");}else{if(c==C::Tempo){++tempo;check(t.tempo()==500000,"Transport defaulttempo");}if(c==C::ReleaseKey)++releases;check(t.resumeChild(),"Transport voidreply");}continue;}auto read=[&](S s)->uint32_t{switch(s){case S::SaveRead:return state[t.index()];case S::RestoreRead:return saved[t.index()];case S::ReadDivision:return 0xbeef;case S::ReadPlaying:return playing;case S::ReadMode:return state[16];default:throw std::runtime_error("Unexpected transportread");}};auto write=[&](S s,uint32_t v){switch(s){case S::PlaybackFlag:check(v==1,"Enable transport");break;case S::SavePublish:saved[t.index()]=uint8_t(v);break;case S::PublishProgram:state[1]=uint8_t(v);break;case S::PublishMulti:state[16]=uint8_t(v);break;case S::PublishTime:case S::PublishDeadline:check(v==0,"Initial resettime");++timeReset;break;case S::PublishDivision:division=v;break;case S::PublishPlaying:check(v==1,"Start fileplaying");playing=true;break;case S::PublishStopped:check(v==0,"Disable transport");++stopped;break;case S::RestorePublish:state[t.index()]=uint8_t(v);break;default:throw std::runtime_error("Unexpected transportwrite");}};auto stage=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&stage==t.stage(),"Early transport deadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Transport deadline");}
check(state==old&&saved==old,"Transport state save/restore18bytes");check(division==0xbeef&&tempo==1&&timeReset==2&&stopped==1&&delays==1,"Transport setup/cleanup");bool exitKey=key>0&&key<128;check(polls==unsigned(!firstDue)&&controls==unsigned(!firstDue&&!exitKey),"Transport signed key decisions");check(releases==unsigned(!firstDue&&!exitKey&&available&&control==27),"Transport controlrelease");check(events==unsigned(firstDue||!exitKey),"Transport event/exit flow");check(children[children.size()-2]==(mode?C::LoadMulti:C::LoadPatch)&&children.back()==C::Refresh,"Transport restored mode job");++cases;};for(unsigned key=0;key<256;++key)for(unsigned control=0;control<256;++control)for(bool available:{false,true})for(unsigned mode:{0u,1u})verify(key,control,available,mode,false);for(unsigned mode=0;mode<256;++mode)verify(0,27,true,mode,true);std::cout<<"PASS: "<<cases<<" pure MIDI-file transport tasks, independent save/restore/key/control/due/EOF/job-order oracles, typed source/results and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
